def transform_demo(grid):
    """Apply the transformation: for each 5 at (r,c), place 5 at (r,c-4) and (r+8,c-3)"""
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]  # Deep copy

    # Find all original 5s
    seed_positions = [(r,c) for r in range(rows) for c in range(cols) if grid[r][c] == 5]

    # Apply transformation
    for r, c in seed_positions:
        # First copy: (r, c-4)
        nc = c - 4
        if nc >= 0 and nc < cols:
            if 0 <= r < rows:  # bounds check
                if result[r][nc] == 0:  # only change 0s
                    result[r][nc] = 5

        # Second copy: (r+8, c-3) from the first copy's position
        nc2 = nc - 4  # (c-3) if nc = c-4
        nr = r + 8
        if nc2 >= 0 and nc2 < cols and 0 <= nr < rows:
            if result[nr][nc2] == 0:
                result[nr][nc2] = 5

    return result

