from collections import deque

def get_connected_components(grid):
    """Find connected components of 0s using 8-connectivity"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '0' and (r, c) not in visited:
                # BFS for 8-connectivity
                comp = set()
                queue = deque([(r, c)])
                visited.add((r, c))
                comp.add((r, c))

                while queue:
                    curr_r, curr_c = queue.popleft()
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == '0' and (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    comp.add((nr, nc))
                                    queue.append((nr, nc))
                components.append(comp)

    return components

